import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { HttpError, CalendarUnavailableError, SlotUnavailableError } from "../src/scheduling/errors.ts";
import { BookingService, type Appointment, type CalendarClient, type Slot } from "../src/scheduling/service.ts";
import { postAppointment, deleteAppointment } from "../src/scheduling/http.ts";
import { Waitlist } from "../src/scheduling/waitlist.ts";

const now = () => new Date("2026-11-19T08:00:00Z");
const START = "2026-11-20T10:00:00.000Z";

// In-memory clinic calendar. `failNext` makes the named call fail once with an HTTP status.
function fakeCalendar(slots: Slot[]) {
    const booked = new Map<string, Appointment>();
    const failNext: { findSlot?: number; reserve?: number } = {};
    let calls = 0;
    const calendar: CalendarClient = {
        async findSlot(providerId, start) {
            calls++;
            await tick();
            if (failNext.findSlot) throw new HttpError(failNext.findSlot, "calendar error");
            const slot = slots.find((s) => s.providerId === providerId && s.start === start);
            return slot && ![...booked.values()].some((a) => a.slotId === slot.id) ? slot : null;
        },
        async reserve(slot, booking) {
            calls++;
            await tick();
            if (failNext.reserve) throw new HttpError(failNext.reserve, "calendar error");
            if ([...booked.values()].some((a) => a.slotId === slot.id)) throw new HttpError(409, "slot already reserved");
            const appt = { id: `appt-${booked.size + 1}`, slotId: slot.id, providerId: slot.providerId, start: slot.start, ...booking };
            booked.set(appt.id, appt);
            return appt;
        },
        async release(id) {
            await tick();
            if (!booked.delete(id)) throw new HttpError(404, "no such appointment");
        },
    };
    return { calendar, booked, failNext, calls: () => calls };
}

const slots: Slot[] = [{ id: "s1", providerId: "dr-okafor", start: START }];
const request = (patientId: string) => ({ patientId, providerId: "dr-okafor", start: START, reason: "knee follow-up" });

test("booking a free slot returns 201 with the appointment", async () => {
    const cal = fakeCalendar(slots);
    const res = await postAppointment(new BookingService(cal.calendar, now), request("p1"));
    assert.equal(res.status, 201);
    assert.equal((res.body as Appointment).slotId, "s1");
});

test("requests with too little notice are rejected with 400 before the calendar is called", async () => {
    const cal = fakeCalendar(slots);
    const res = await postAppointment(new BookingService(cal.calendar, now), { ...request("p1"), start: "2026-11-19T09:00:00Z" });
    assert.equal(res.status, 400);
    assert.equal(cal.calls(), 0);
});

test("when two patients race for the same slot, the loser gets 409 slot_taken", async () => {
    const cal = fakeCalendar(slots);
    const service = new BookingService(cal.calendar, now);
    const [a, b] = await Promise.all([postAppointment(service, request("p1")), postAppointment(service, request("p2"))]);
    console.log("responses:", [a.status, b.status], "loser body:", a.status === 201 ? b.body : a.body);
    assert.deepEqual([a.status, b.status].sort(), [201, 409]);
    const loser = a.status === 201 ? b : a;
    assert.equal((loser.body as { code: string }).code, "slot_taken");
});

test("a calendar outage while looking up the slot is a 503 with Retry-After", async () => {
    const cal = fakeCalendar(slots);
    cal.failNext.findSlot = 503;
    const res = await postAppointment(new BookingService(cal.calendar, now), request("p1"));
    assert.equal(res.status, 503);
    assert.equal(res.headers?.["Retry-After"], "15");
});

test("a calendar outage while reserving is reported as CalendarUnavailableError", async () => {
    const cal = fakeCalendar(slots);
    cal.failNext.reserve = 429;
    const service = new BookingService(cal.calendar, now);
    await assert.rejects(service.book(request("p1")), (err: unknown) => {
        assert.ok(err instanceof CalendarUnavailableError, `got ${(err as Error).name}`);
        assert.equal(err.retryAfterSeconds, 60);
        assert.equal((err.cause as HttpError).status, 429);
        return true;
    });
});

test("a patient who loses the race for a slot is put on the waitlist", async () => {
    const cal = fakeCalendar(slots);
    const waitlist = new Waitlist(new BookingService(cal.calendar, now));
    const results = await Promise.all([waitlist.bookOrJoin(request("p1")), waitlist.bookOrJoin(request("p2"))]);
    assert.deepEqual(results.map((r) => r.status), ["booked", "waitlisted"]);
    assert.deepEqual(waitlist.waiting("dr-okafor"), ["p2"]);
});

test("a time with no slot at all also goes to the waitlist", async () => {
    const cal = fakeCalendar(slots);
    const waitlist = new Waitlist(new BookingService(cal.calendar, now));
    const result = await waitlist.bookOrJoin({ ...request("p3"), start: "2026-11-20T11:00:00Z" });
    assert.deepEqual(result, { status: "waitlisted", position: 1 });
    await assert.rejects(new BookingService(cal.calendar, now).book({ ...request("p3"), start: "2026-11-20T11:00:00Z" }), SlotUnavailableError);
});

test("cancelling an unknown appointment is a 404", async () => {
    const cal = fakeCalendar(slots);
    const res = await deleteAppointment(new BookingService(cal.calendar, now), "appt-404");
    assert.equal(res.status, 404);
});
